    enonce: "<span class=\"q\">1) </span>اجعل المقام ناطقا: <span dir=\"ltr\" class=\"expr\">A = 5/(4 + √10)</span><br><span class=\"q\">2) </span>اجعل المقام ناطقا: <span dir=\"ltr\" class=\"expr\">A = 10/(2√15)</span><br><span class=\"q\">3) </span>اجعل المقام ناطقا: <span dir=\"ltr\" class=\"expr\">A = 8/(4 + 2√11)</span><br><span class=\"q\">4) </span>اجعل المقام ناطقا: <span dir=\"ltr\" class=\"expr\">A = 3/(3√13)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نستعمل المرافق<span dir=\"ltr\" class=\"expr\">: (a + b)(a - b) = a<sup>2</sup> - b<sup>2</sup></span>، و المربّع يُزيل الجذر"},{"quoi":"المرافق","math":"مرافق المقام هو <span dir=\"ltr\" class=\"expr\">4 - √10</span>"},{"quoi":"نضرب في المرافق","math":"<span dir=\"ltr\" class=\"expr\">A = 5(4 - √10)/((4 + √10)(4 - √10))</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">(4)<sup>2</sup> - (√10)<sup>2</sup> = 16 - 10 = 6</span>"},{"quoi":"نعيد الكتابة","math":"<span dir=\"ltr\" class=\"expr\">A = 5(4 - √10)/6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">10</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> √10</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"نضرب البسط و المقام في نفس العدد: قيمة الكسر لا تتغيّر"},{"quoi":"نضرب في √15","math":"<span dir=\"ltr\" class=\"expr\">A = 10√15/(2√15 × √15)</span>"},{"quoi":"الجذر يختفي من المقام","math":"<span dir=\"ltr\" class=\"expr\">√15 × √15 = 15</span>"},{"quoi":"نعيد الكتابة","math":"<span dir=\"ltr\" class=\"expr\">A = 10√<span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">30</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> √15</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"القاعدة","math":"نستعمل المرافق<span dir=\"ltr\" class=\"expr\">: (a + b)(a - b) = a<sup>2</sup> - b<sup>2</sup></span>، و المربّع يُزيل الجذر"},{"quoi":"المرافق","math":"مرافق المقام هو <span dir=\"ltr\" class=\"expr\">4 - 2√11</span>"},{"quoi":"نضرب في المرافق","math":"<span dir=\"ltr\" class=\"expr\">A = 8(4 - 2√11)/((4 + 2√11)(4 - 2√11))</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">(4)<sup>2</sup> - (2√11)<sup>2</sup> = 16 - 44 = -28</span>"},{"quoi":"نعيد الكتابة","math":"<span dir=\"ltr\" class=\"expr\">A = 8(4 - 2√11)/-28</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = -<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">7</span></span> + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">7</span></span> √11</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"القاعدة","math":"نضرب البسط و المقام في نفس العدد: قيمة الكسر لا تتغيّر"},{"quoi":"نضرب في √13","math":"<span dir=\"ltr\" class=\"expr\">A = 3√13/(3√13 × √13)</span>"},{"quoi":"الجذر يختفي من المقام","math":"<span dir=\"ltr\" class=\"expr\">√13 × √13 = 13</span>"},{"quoi":"نعيد الكتابة","math":"<span dir=\"ltr\" class=\"expr\">A = 3√<span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">39</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">13</span></span> √13</span>"}],
